const reference='../index.html#d03-service-and-siting';
const choice=(key,label,options)=>({key,label,options});
export const generationInitialState=Object.freeze({genCycle:'simple',genCampus:0,genStart:'hot',genHours:500,genChoiceHours:7000,genChoiceReveal:false});
export const generationScenes=[
 {id:'gas-shaft',label:'What turns the generator?',title:'Expanding combustion gas drives the compressor and generator.',reference,boundary:'Conceptual open-cycle gas turbine · steady operation, after startup.',explanation:['Air enters a compressor, fuel burns in the compressed air, and the hot gas expands through turbine blades. The turbine supplies shaft work to both the compressor and the electric generator. This gas-turbine process is modeled by the Brayton cycle. A starter may initially turn the shaft; a continuously powered electric motor is not the fuel-to-electricity mechanism.','Open cycle, or simple-cycle gas turbine, describes the gas leaving through the exhaust without a second steam power cycle. Peaking is an operating role. Gas turbines can do other jobs, and peaking power can also come from engines, storage or other resources.']},
 {id:'combined-cycle',label:'Recover the exhaust heat',title:'A second turbine turns exhaust heat into more electricity.',reference,boundary:'Conceptual combined cycle · separate exhaust-gas and water/steam paths · no supplementary firing.',explanation:['A heat recovery steam generator, or HRSG, transfers heat from the gas-turbine exhaust into a separate pressurized water/steam circuit. Steam expands through a steam turbine, which drives a generator. A condenser removes remaining heat and returns steam to liquid; a pump returns that water to the HRSG. This steam power loop is modeled by the Rankine cycle.','The exhaust gas does not become the steam. Combining the gas and steam cycles recovers energy that a simple-cycle plant would otherwise reject. It also adds the HRSG, steam turbine, condenser, cooling and water systems. Those additions affect capital, space, construction, maintenance and startup requirements. The combined-cycle plant still rejects heat.']},
 {id:'generation-fuel',label:'Hold electrical output fixed',title:'Recovering exhaust heat reduces the fuel needed for 100 MW.',reference,boundary:'Hypothetical plants · 100 MW net electric output · 40% or 60% efficiency, LHV basis.',controls:[choice('genCycle','Power cycle',[['simple','Simple cycle'],['combined','Combined cycle']])],explanation:['Hold net electrical output at 100 MW. At the assumed 40% net efficiency, fuel enters at 250 MW of thermal energy; at 60%, it enters at 166.7 MW. The difference is fuel required for the same delivered electricity. We are comparing equal-output plant options, not claiming a steam retrofit leaves the same gas turbine’s total output unchanged.','The remainder, 150 MW or 66.7 MW on this simplified lower-heating-value balance, includes unrecovered exhaust energy, cooling and other losses. The two percentages are teaching assumptions, not Dania Beach measurements or universal technology ratings. Fuel-energy comparisons must use the same heating-value convention.']},
 {id:'dania-cycle',label:'See the actual plant',title:'Dania Beach’s combined cycle includes two gas turbines.',reference,boundary:'GE Vernova’s Dania Beach case · reported plant output up to 1,260 MW · source reviewed 12 September 2026.',explanation:['The manufacturer’s photograph places this mechanism in a real utility plant: FPL’s Dania Beach Clean Energy Center near Fort Lauderdale. GE Vernova reports two 7HA.03 gas turbines and plant output up to 1,260 MW. That number describes the reported plant, not two standalone turbine nameplates added together.','This is a grid-generation example, not an asserted supply contract or electrical connection to our course campus. The earlier 100 MW / 40% / 60% calculation remains hypothetical. Do not infer this site’s instantaneous output, operating efficiency or allocation to data centers from its published capacity.']},
 {id:'grid-dispatch',label:'Supply each hour',title:'A steady campus load can exhaust the grid’s peak headroom.',reference,boundary:'Hypothetical shared grid · fully available 100 + 120 + 80 MW · no ramp, reserve or network constraints.',controls:[choice('genCampus','Additional steady campus load',[[0,'No added campus'],[50,'Add 50 MW']])],explanation:['Baseload means the demand present throughout the interval. Intermediate or mid-merit duty supplies demand above that floor for longer periods; peaking duty covers shorter high-demand intervals. In this simplified stack, an assumed 100 MW contribution runs throughout, combined cycle supplies the next 120 MW and simple-cycle peaking supplies up to 80 MW. The combined-cycle contribution changes across the day: it is not inherently locked at one output.','Add a constant 50 MW campus while leaving capacity fixed. The baseline peak rises from 260 to 310 MW, exceeding the available 300 MW by 10 MW. A flat campus load still consumes capacity at the grid’s hardest hour. Actual dispatch also depends on other generation, storage, renewable output, fuel cost, startup, ramping, minimum load, reserves and transmission; this is not a dispatch forecast or an adequacy assessment.']},
 {id:'generation-flexibility',label:'Combined cycle can follow load',title:'A hot-start rating does not tell you the cold-start time.',reference,boundary:'GE 7HA.03, 1×1 combined-cycle catalog · May 2025 · net plant, ISO conditions, natural gas.',controls:[choice('genStart','Initial condition',[['hot','Hot plant'],['cold','Cold plant']])],explanation:['The May 2025 GE Vernova fact sheet lists a 7HA.03 1×1 combined-cycle plant at 640 MW net, with a rapid-response hot start below 30 minutes, a 75 MW/minute ramp rate and a 26% minimum-load entry. These are separate catalog characteristics; the hot-start number cannot be reused for a cold plant, and the ramp rate is not a promise of instantaneous service from zero.','Combined cycle can follow load and serve intermediate duty. Simple cycle often has a simpler installation and can suit short-notice operation, but startup depends on the actual machine and thermal state. Building a plant, starting an available plant and changing its running output are three different clocks. Equipment procurement, permits, fuel supply and civil work can dominate either construction schedule.']},
 {id:'generation-utilization',label:'When does efficiency repay?',title:'More running hours can repay the extra steam-cycle equipment.',reference,boundary:'Hypothetical 100 MW options · annualized fixed cost $8M / $16M · fuel $20/MWh thermal, LHV.',controls:[choice('genHours','Equivalent full-load hours per year',[[500,'500 h'],[4800,'4,800 h'],[7000,'7,000 h']])],explanation:['Use the same 40% and 60% efficiencies, with hypothetical annualized fixed costs of $8 million for simple cycle and $16 million for combined cycle. At a fuel price of $20 per MWh thermal on the same LHV basis, variable fuel costs are $50 and $33.33 per MWh electric. Equal output capability does not imply equal annual cost.','At 500 equivalent full-load hours, simple cycle costs $10.5 million against $17.67 million. At 7,000 hours, combined cycle costs $39.33 million against $43 million. The crossover is 4,800 hours in this model. These are original assumptions, not market quotations or an investment recommendation. Start costs, variable maintenance, emissions costs, part-load efficiency, downtime and project-specific financing are excluded.']},
 {id:'generation-choice',label:'Choose the duty first',title:'Choose the plant for the service interval it must actually cover.',reference,boundary:'Same hypothetical 100 MW cost model · both options assumed deliverable and capable of the required service.',controls:[choice('genChoiceHours','Required annual duty',[[500,'500 full-load hours'],[7000,'7,000 full-load hours']])],reveal:'genChoiceReveal',explanation:['Predict which option has the lower annual cost before revealing. Under the supplied assumptions, simple cycle wins for 500 hours and combined cycle wins for 7,000. The economic answer changes with duty, even though the more efficient plant remains more efficient in both cases.','Then return to site delivery: can that option be built by the service date, receive its required fuel and cooling, and meet the relevant start, ramp and contingency requirements? A cheaper modeled year is irrelevant if the promised load cannot be served. A combined-cycle plant may be useful for sustained supply; its presence does not by itself establish an island-capable or fault-tolerant data center.']},
];

export function generationBalance(cycle){
 if(!['simple','combined'].includes(cycle))throw new RangeError('Unknown power cycle');
 const efficiency=cycle==='simple'?.4:.6,netMW=100,fuelMW=netMW/efficiency;
 return {efficiency,netMW,fuelMW,remainderMW:fuelMW-netMW};
}
const dailyDemand=Object.freeze([130,120,110,100,100,110,130,160,185,205,220,230,240,250,260,260,250,245,230,215,195,175,155,140]);
export function dispatchDay(campusMW=0){
 if(!Number.isFinite(campusMW)||campusMW<0)throw new RangeError('Campus load must be finite and nonnegative');
 return dailyDemand.map((baselineMW,hour)=>{const demandMW=baselineMW+campusMW,baseMW=100,combinedMW=Math.min(120,demandMW-baseMW),peakerMW=Math.min(80,Math.max(0,demandMW-baseMW-combinedMW)),shortfallMW=demandMW-baseMW-combinedMW-peakerMW;return{hour,demandMW,baseMW,combinedMW,peakerMW,shortfallMW};});
}
export function generationCosts(hours){
 if(!Number.isFinite(hours)||hours<0||hours>8760)throw new RangeError('Hours must be between 0 and 8760');
 const simpleFuelPerMWh=20/.4,combinedFuelPerMWh=20/.6,simpleFixed=8e6,combinedFixed=16e6;
 const simpleTotal=simpleFixed+100*hours*simpleFuelPerMWh,combinedTotal=combinedFixed+100*hours*combinedFuelPerMWh;
 return {hours,simpleTotal,combinedTotal,simpleFixed,combinedFixed,simpleFuelPerMWh,combinedFuelPerMWh,crossoverHours:(combinedFixed-simpleFixed)/(100*(simpleFuelPerMWh-combinedFuelPerMWh)),winner:Math.abs(simpleTotal-combinedTotal)<.01?'equal':simpleTotal<combinedTotal?'simple':'combined'};
}
const C={ink:'var(--text)',muted:'var(--muted)',line:'var(--line)',face:'var(--surface)',panel:'var(--panel)',power:'var(--power)',heat:'var(--heat)',data:'var(--data)',paper:'var(--paper)'};
