const line=(x,y,x2,y2,color=C.line,width=3,dash='')=>`<path d="M${x} ${y}L${x2} ${y2}" fill="none" stroke="${color}" stroke-width="${width}" ${dash?'stroke-dasharray="'+dash+'"':''}/>`;
const arrow=(x,y,x2,y2,c=C.power)=>{const a=Math.atan2(y2-y,x2-x),d=9;return line(x,y,x2,y2,c,4)+`<path d="M${x2-d*Math.cos(a-.45)} ${y2-d*Math.sin(a-.45)}L${x2} ${y2}L${x2-d*Math.cos(a+.45)} ${y2-d*Math.sin(a+.45)}" fill="none" stroke="${c}" stroke-width="3"/>`;};
const box=(x,y,w,h,a,b='',c=C.power)=>rect(x,y,w,h,C.face,c)+t(x+w/2,y+h/2+(b?-6:8),a,w<180?18:23,C.ink,'middle')+(b?t(x+w/2,y+h/2+22,b,w<180?15:17,C.muted,'middle'):'');
