 [0,6,12,18,24].forEach(v=>o+=t(x+w*v/24,y+h+25,`${v} h`,m?13:16,C.muted,v===0?'start':v===24?'end':'middle'));
 const max=Math.max(...day.map(d=>d.demandMW)),gap=Math.max(...day.map(d=>d.shortfallMW));o+=t(m?195:560,m?459:416,`Peak: ${max} MW · available: 300 MW`,m?21:29,gap?C.heat:C.ink,'middle');
