export function renderGeneration(id,state,compact=false){const s={...generationInitialState,...state},renders={'gas-shaft':()=>shaft(compact),'combined-cycle':()=>combined(compact),'generation-fuel':()=>fuelBalance(s,compact),'dania-cycle':()=>dania(compact),'grid-dispatch':()=>dispatch(s,compact),'generation-flexibility':()=>flexibility(s,compact),'generation-utilization':()=>costs(s,compact),'generation-choice':()=>costs(s,compact,true)};if(!renders[id])throw new Error(`Unknown generation scene: ${id}`);return renders[id]();}
